function validate(input) {
  const [{ Traffic = [] }] = input;
  const kinds = ['login', 'logout', 'jobs', 'groups', 'homepage'];
  for (const [user, activity, date] of Traffic) {
    if (user === null || activity === null || date === null) return 'user_id, activity and activity_date are required.';
    if (!kinds.includes(activity)) return `Unknown activity ${activity}.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `activity_date ${date} is not YYYY-MM-DD.`;
    if (date > '2019-06-30') return `activity_date ${date} is after today, 2019-06-30.`;
  }
  return null;
}

