function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const kinds = ['login', 'login', 'login', 'logout', 'jobs', 'groups', 'homepage'];
  const day = offset => new Date(Date.UTC(2019, 5, 30 - offset)).toISOString().slice(0, 10);
  const Traffic = [];
  if (size === 'small') {
    // Offsets cluster around the 90-day boundary (2019-04-01) and today.
    const offsets = [0, 1, 9, 89, 90, 91, 120];
    const users = 1 + pick(4), rows = pick(9);
    for (let i = 0; i < rows; i++) {
      if (Traffic.length && rand() < 0.15) { Traffic.push([...Traffic[pick(Traffic.length)]]); continue; }
      Traffic.push([1 + pick(users), kinds[pick(kinds.length)], day(offsets[pick(offsets.length)])]);
    }
  } else {
    for (let i = 0; i < 2000; i++) Traffic.push([1 + pick(400), kinds[pick(kinds.length)], day(pick(180))]);
  }
  return [{ Traffic }];
}
